import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { loginUser } from "../services/api"; 
import { Box, TextField, Button, Typography, Grid, Card, CardContent } from "@mui/material";

const Login = () => {
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const [errorMessage, setErrorMessage] = useState(""); // For displaying error messages
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrorMessage(""); // Reset error message on new attempt
    
        try {
            const { data } = await loginUser({ username, password });
            console.log("API Response:", data); // Log the response to inspect it
    
            // Check if the data and token exist before using them
            if (data && data.token) {
                localStorage.setItem("token", data.token);
    
                // Navigate based on the user's role
                if (data.user && data.user.role === "superadmin") {
                    navigate("/superadmin");
                } else if (data.user && data.user.role === "admin") {
                    navigate("/admin");
                } else {
                    navigate("/user");
                }
            } else {
                setErrorMessage("Invalid Credentials");
            }
        } catch (error) {
            console.error("Login failed:", error);
            setErrorMessage("An error occurred. Please try again later.");
        }
    };
    

    return (
        <Grid
            container
            alignItems="center"
            justifyContent="center"
            style={{ minHeight: "100vh", backgroundColor: "#f5f5f5" }}
        >
            <Grid item xs={11} sm={8} md={4}>
                <Card elevation={6} style={{ borderRadius: "12px" }}>
                    <CardContent>
                        <Box textAlign="center" mb={3}>
                            <Typography variant="h4" component="h1" gutterBottom>
                                Login
                            </Typography>
                            <Typography variant="body1" color="textSecondary">
                                Please enter your credentials to access the application.
                            </Typography>
                        </Box>
                        
                        {errorMessage && (
                            <Typography variant="body2" color="error" align="center" gutterBottom>
                                {errorMessage}
                            </Typography>
                        )}

                        <form onSubmit={handleSubmit}>
                            <TextField
                                label="Username"
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                fullWidth
                                margin="normal"
                                variant="outlined"
                            />
                            <TextField
                                label="Password"
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                fullWidth
                                margin="normal"
                                variant="outlined"
                            />
                            <Box mt={3}>
                                <Button
                                    type="submit"
                                    variant="contained"
                                    color="primary"
                                    fullWidth
                                    size="large"
                                    style={{ textTransform: "none" }}
                                >
                                    Login
                                </Button>
                            </Box>
                        </form>
                    </CardContent>
                </Card>
            </Grid>
        </Grid>
    );
};

export default Login;
